#define ARRAY_SIZE 4
#define MAX_STEPS 100.0
#define PI 3.14159265359

vec4 getTextureByID(int id, vec2 uv) {
    if (id == 0) return texture(iChannel0, uv);
    if (id == 1) return texture(iChannel1, uv);
    if (id == 2) return texture(iChannel2, uv);
    if (id == 3) return texture(iChannel3, uv);
    return vec4(0.0);
}

float sdSphere(vec3 p, vec3 center, float radius) 
{
    //do not render behind the spheres
    if (p.z < center.z) return MAX_STEPS;

    //length = vector magnetude = sqrt(p.x * p.x + p.y * p.y + p.z * p.z);
    return length(p - center) - radius;
}

float minimo(vec3 p, vec4 vectors[ARRAY_SIZE], out int minimoID)
{
    //verify IF the current ray is enought close(epsilon) from "some point" of "some sphere"

    float m = MAX_STEPS;
    for (int i = 0; i < ARRAY_SIZE; i++) {
        float d = sdSphere(p, vectors[i].xyz, vectors[i].w);
        if (d < m)
        {
            m = d;
            minimoID = i;
        }
    }
    return m;
}

vec3 calcNormal(vec3 p, vec3 center, float r, float epsilon) 
{
    float dx = sdSphere(p + vec3(epsilon, 0.0, 0.0), center, r) - sdSphere(p - vec3(epsilon, 0.0, 0.0), center, r);
    float dy = sdSphere(p + vec3(0.0, epsilon, 0.0), center, r) - sdSphere(p - vec3(0.0, epsilon, 0.0), center, r);
    float dz = sdSphere(p + vec3(0.0, 0.0, epsilon), center, r) - sdSphere(p - vec3(0.0, 0.0, epsilon), center, r);
    return normalize(vec3(dx, dy, dz));
}

float mapAuxiliaryValue(float x) 
{
    return max(0.0, min((x - 0.8) * 2.0, 1.0));
}

float triangularWave(float x) 
{
    return (1.0 - abs(2.0 * x - 1.0));
}

void mainImage(out vec4 fragColor, in vec2 fragCoord)
{
    float pos = iMouse.x / iResolution.x;

    vec2 uv = (fragCoord - 0.5 * iResolution.xy) / iResolution.y;

    vec3 rayOrigin = vec3(0.0, 0.0, 3.0);
    vec3 rayDir = normalize(vec3(uv, -1.0));

    float depth = 0.0;
    vec3 hitPoint;
    const float epsilon = 0.0001;
    const float maxDist = 10.0;

    int hit = 0;
    int minimoID = -1;

    vec4 vectors[ARRAY_SIZE];
    //vectors[0] = vec4(sin(iTime * 0.02 - 2.0), 0.0, 0.0, 0.5);
    vectors[0] = vec4(0.0, 0.0, 0.0, 0.5);
    vectors[1] = vec4(vectors[0].x + sin(iTime) * 1.2, vectors[0].y, vectors[0].z + cos(iTime) * 1.2, 0.2);
    vectors[2] = vec4(vectors[0].x + sin(iTime * 0.5 + 1.0) * 2.2, vectors[0].y, vectors[0].z + cos(iTime * 0.5 + 1.0) * 2.2, 0.1);
    vectors[3] = vec4(vectors[0].x + sin(iTime * 0.5 + -1.0) * 2.2, vectors[0].y, vectors[0].z + cos(iTime * 0.5 - 1.0) * 2.2, 0.2);

    float pastColor = 1.0;
    vec3 comutativeColor = vec3(0.0, 0.0, 0.0);
    for (int i = 0; i < int(MAX_STEPS); i++) 
    {
        //cast one ray for each pixel for each step(T0, T1, T2... TmaxSteps) 
        hitPoint = rayOrigin + rayDir * depth;

        //float dist = min(d1, d2);
        float dist = minimo(hitPoint, vectors, minimoID);

        if (dist < epsilon) 
        {
            hit += 1;
            //depth += 3.0;

            //if find the colision point in some step of te ray
            vec3 n = calcNormal(hitPoint, vectors[minimoID].xyz, vectors[minimoID].w, epsilon);
            float b = max(0.0, dot(n, vec3(0.677)));

            //texture maped to sphere
            float u = 0.5 + atan(n.z, n.x) / (2.0 * PI);
            float v = 0.5 - asin(n.y) / PI;
            vec2 mapUV = vec2(u + (iTime * (15.43 - vectors[minimoID].w) * 0.005), v);

            vec3 surface = getTextureByID(minimoID, mapUV).rgb;

            //atmosphere effect
            vec3 r1 = normalize(rayOrigin - vectors[minimoID].xyz);
            vec3 r2 = normalize(hitPoint - vectors[minimoID].xyz);

            float dotProduct = clamp(dot(r1, r2), -1.0, 1.0);
            float angle = acos(dotProduct);
            float atmosphere = triangularWave(smoothstep(0.0, 1.0, mapAuxiliaryValue(angle)));

            //color result
            surface *= 1.0 - smoothstep(0.0, 1.0, mapAuxiliaryValue(angle + 0.15));
            surface += atmosphere * vec3(0.1, 0.5 + vectors[minimoID].w, 1.0 - vectors[minimoID].w) * 1.0 * (1.0 - vectors[minimoID].w);

            vec3 sphereColors = (vec3(1.0) * (b * surface) + 0.01);

            //transparence
            comutativeColor += sphereColors * pastColor;
            depth += vectors[minimoID].w * 2.0;
            pastColor = smoothstep(0.2, 1.0, mapAuxiliaryValue(angle));

            //maximun of transparence layers
            if (hit >= 5) break;
        }

        if (depth > maxDist) break;

         //if do not find the sphere colision point in that step, run to next (T0, T1, T2... TmaxSteps) 
        depth += dist;
    }

    fragColor = vec4(comutativeColor, 1.0);
    //fragColor = vec4(surface, 1.0);
}
